/**
 * function setDraggable
 * 设置DOM元素是否可拖动（用于窗口拖动）
 * @param {HTMLElement} domElement - 需要控制拖动的DOM元素
 * @param {boolean} draggable - 是否启用拖动功能
 */
// 替代的 setDraggable 函数
function setDraggable(domElement, draggable) {
    if (!(domElement instanceof HTMLElement)) {
        throw new Error('第一个参数必须是有效的DOM元素');
    }

    const handlerKey = '__dragHandler__';

    // 移除现有拖动事件
    if (domElement[handlerKey]) {
        domElement.removeEventListener('mousedown', domElement[handlerKey]);
        delete domElement[handlerKey];
    }

    if (draggable) {
        const dragHandler = (event) => {
            // 检查点击目标是否是按钮或按钮的子元素
            const isControlButton = event.target.closest('.title-bar-controls') ||
                event.target.closest('.title-bar-btn');

            // 如果是控制按钮，不触发拖动
            if (isControlButton) {
                return;
            }

            // 防止拖动时选中文本
            event.preventDefault();

            // 调用窗口拖动API
            if (window.Niva && window.Niva.api && window.Niva.api.window) {
                Niva.api.window.dragWindow();
            } else {
                console.warn('Niva API 未找到');
            }
        };

        // 存储处理函数引用
        domElement[handlerKey] = dragHandler;
        // 注册鼠标按下事件
        domElement.addEventListener('mousedown', dragHandler);
    }
}


/**
 * 获取屏幕分辨率
 * @returns {Promise<{ width: number, height: number }>} - 屏幕分辨率
 */
async function getScreenResolution() {
    const osInfo = await Niva.api.os.info();
    const osType = osInfo.os;

    if (osType === 'Windows') {
        return new Promise((resolve, reject) => {
            Niva.api.process.exec(
                'wmic',
                ['path', 'Win32_VideoController', 'get', 'CurrentHorizontalResolution,CurrentVerticalResolution'],
                { silent: true }
            ).then(result => {
                const lines = result.stdout.split('\n');
                for (const line of lines) {
                    const match = line.match(/\s*(\d+)\s+(\d+)\s*/);
                    if (match && match.length === 3) {
                        return resolve({
                            width: parseInt(match[1], 10),
                            height: parseInt(match[2], 10)
                        });
                    }
                }
                reject(new Error('No valid resolution found in output'));
            }).catch(reject);
        });
    } else {
        return new Promise((resolve, reject) => {
            Niva.api.process.exec(
                'system_profiler',
                ['SPDisplaysDataType'],
                { silent: true }
            ).then(result => {
                const lines = result.stdout.split('\n');
                for (const line of lines) {
                    const match = line.match(/Resolution:\s*(\d+)\s*x\s*(\d+)/);
                    if (match && match.length === 3) {
                        return resolve({
                            width: parseInt(match[1], 10),
                            height: parseInt(match[2], 10)
                        });
                    }
                }
                reject(new Error('No valid resolution found in output'));
            }).catch(reject);
        });
    }
}